const studioHtml = r'''<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Torchinlane Studio</title>
<style>
:root{color-scheme:dark;--bg:#10131b;--panel:#1a2030;--line:#30394f;--muted:#aeb9cd;--accent:#ffad64}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#eef2fa;font:15px system-ui,sans-serif}header{padding:24px 5%;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:16px;align-items:center}h1{font-size:24px;margin:0}small,.hint{color:var(--muted)}nav{padding:18px 5%;display:flex;gap:10px;flex-wrap:wrap}button{border:1px solid var(--line);background:#253049;color:#eef2fa;padding:10px 16px;border-radius:8px;cursor:pointer;font:inherit}button:hover,button.active{border-color:var(--accent)}button.primary{background:var(--accent);color:#21160b;font-weight:650}button:disabled{opacity:.5;cursor:not-allowed}main{max-width:1100px;margin:auto;padding:12px 24px 70px}.card{background:var(--panel);padding:24px;border-radius:14px;border:1px solid var(--line);margin:0 0 20px}h2{font-size:20px;margin-top:0}h3{font-size:16px}label{display:block;color:var(--muted);margin:16px 0 7px}input,select,textarea{background:#101725;border:1px solid #3b4862;color:#eef2fa;border-radius:7px;padding:10px;width:100%;font:inherit}textarea{min-height:95px;resize:vertical}.row{display:flex;gap:16px;flex-wrap:wrap;align-items:flex-end}.row>div{flex:1;min-width:150px}.row.buttons{margin-top:20px;align-items:center}input[type=checkbox]{width:auto}input[type=file]{max-width:450px}a{color:#ffbf89}.hidden{display:none!important}.status{padding:12px 5%;background:#202b3c;white-space:pre-wrap;overflow-wrap:anywhere}.counter{font-size:12px;color:var(--muted);text-align:right}.counter.invalid{color:#ff8c8c}.gallery{display:flex;gap:12px;flex-wrap:wrap}.image{width:150px;background:#111827;padding:8px;border-radius:8px}.image img{width:100%;height:190px;object-fit:contain}.image button{padding:5px;margin:3px;font-size:12px}.image small{display:block;overflow-wrap:anywhere}pre{background:#0b1019;padding:16px;max-height:350px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}.check{display:flex;align-items:center;gap:8px}footer{color:var(--muted);margin-top:20px}.badge{font-size:12px;padding:6px 10px;border-radius:20px;background:#303c55}details{margin-top:18px}summary{cursor:pointer;color:#ffbf89}.checklist{list-style:none;padding:0}.checklist li{border-top:1px solid var(--line);padding:16px 0;display:flex;align-items:center;gap:14px}.checklist .text{flex:1}.checklist small{display:block;margin-top:5px}.mark{padding:6px 10px;border-radius:8px;font-size:12px;white-space:nowrap;background:#303c55}.mark.done{background:#183f35;color:#a0edc9}.mark.missing{background:#493528;color:#ffcd9e}.steps{line-height:1.8;padding-left:22px}.notice{border-left:3px solid var(--accent);padding:12px 16px;background:#202b3c}.empty{padding:20px 0;color:var(--muted)}#taskPanel textarea{min-height:260px}.context{padding:16px 24px}.step-footer{display:flex;justify-content:space-between;gap:16px;margin:20px 0}@media(max-width:600px){main{padding:10px 14px 40px}.card{padding:18px}.checklist li{flex-wrap:wrap}.checklist .text{min-width:180px}.row{gap:10px}nav{gap:6px}nav button{padding:8px 10px}header{padding:18px}h1{font-size:20px}}
</style></head><body>
<header><div><h1>🔥 Torchinlane Studio</h1><small>Kurulumu kontrol et, metinleri hazırla, mağazaya gönder.</small></div><span class="badge" id="appName">Flutter projesi</span></header>
<nav><button class="active" data-tab="home">Başlangıç</button><button data-tab="setup">1. Kurulum</button><button data-tab="content">2. Metinler</button><button data-tab="translation">3. Çeviri</button><button data-tab="artwork">4. Görseller</button><button data-tab="release">5. Gönder</button></nav>
<div class="status" id="status" role="status">Proje kontrol ediliyor…</div><main>
<section id="home"><div class="card"><h2>Nereden devam etmelisin?</h2><p class="hint">Mevcut ayar ve dosyalar kontrol edilir. Tamamlanan işleri tekrar yapmana gerek yok. Yalnızca kullanacağın mağazayı seç.</p><div class="row"><div><label for="wizardPlatform">Hedef mağaza</label><select id="wizardPlatform"><option value="ios,android">App Store ve Google Play</option><option value="android">Yalnızca Google Play</option><option value="ios">Yalnızca App Store</option></select></div><button id="refreshChecks">Dosyaları tekrar kontrol et</button></div><p id="overviewSummary" class="notice"></p><div id="readinessCards"></div><button class="primary" id="continueWizard">Önerilen adıma git</button><p class="hint">Metin hazırlamak ve çeviri görevi oluşturmak için anahtar veya API bağlantısı gerekmez. Mağaza bağlantısı yalnızca yükleme için; imzalama ise uygulama build'i için gerekir.</p></div></section>
<div id="contentContext" class="card context hidden"><div class="row"><div><label for="platform">Mağaza</label><select id="platform"><option value="ios">App Store</option><option value="android">Google Play</option></select></div><div><label for="locale">Düzenlenen dil</label><select id="locale"></select></div></div><p class="hint" id="contextHint"></p></div>
<section id="content" class="hidden"><div class="card"><h2>2. Önce kaynak metinlerini yaz</h2><p class="hint">Uygulama adını, açıklamasını ve sürüm notlarını bildiğin dilde yaz. Hazır metinler varsa değiştirmene gerek yok. Boş alanlar mevcut mağaza metinlerini silmez.</p><div id="sourceHint" class="notice"></div><div class="row buttons"><button id="editSource">Kaynak dili aç</button><button id="copySource">Diğer mağazadan kaynak metni al</button></div><div id="editor"></div><div class="row buttons"><button class="primary" id="save">Metinleri kaydet</button><button id="validate">Kaydedilen metinleri kontrol et</button></div></div><div class="step-footer"><button data-go="setup">← Kurulum</button><button data-go="translation">Çeviriye geç →</button></div></section>
<section id="translation" class="hidden"><div class="card"><h2>3. Diğer dilleri doldur</h2><ol class="steps"><li>Aşağıdan istediğin dilleri ekle. Zaten ekli dilleri tekrar seçmene gerek yok.</li><li><strong>Çeviri görevini hazırla</strong> ve <strong>Görevi kopyala</strong> düğmelerine bas.</li><li>Flutter projen içinde çalışan Claude Code veya Codex'e yapıştır. Ajan dosyaları doldursun.</li><li>Buraya dön ve <strong>Sonuçları yükle ve kontrol et</strong> düğmesine bas.</li></ol><p class="hint">Ayrı çeviri API anahtarı gerekmez. Apple/Google dil kodları ve metin sınırları göreve otomatik eklenir. Dolu çeviriler korunur.</p><p id="translationProgress" class="notice"></p><div class="row"><div><label for="addLocale">Eklenecek dil</label><select id="addLocale"></select></div><button id="addLocaleButton">Dili ekle</button><div><label for="from">Hangi dilden çevrilecek?</label><select id="from"></select></div></div><div class="row buttons"><button class="primary" id="prepareTask">Çeviri görevini hazırla</button><button id="reloadTranslations">Sonuçları yükle ve kontrol et</button></div><details><summary>İleri seçenekler</summary><button id="allLocales">Desteklenen bütün dilleri ekle</button><label class="check"><input type="checkbox" id="overwrite">Dolu çevirileri de yeniden yaz</label><p class="hint">İstersen doğrudan Anthropic API kullanabilirsin. Bu seçenek API anahtarı gerektirir ve ayrıca ücretlendirilebilir.</p><button id="translate">İsteğe bağlı API ile çevir</button></details><div id="taskPanel" class="hidden"><h3>Görevi ajanına yapıştır</h3><p class="hint">Claude Code/Codex bu Flutter projesinde açık olmalı. İşlem tamamlandığında aşağıdaki sonuç kontrolüne geç.</p><label for="agentTask">Hazır çeviri görevi</label><textarea id="agentTask" readonly rows="14"></textarea><div class="row buttons"><button class="primary" id="copyTask">Görevi kopyala</button></div></div></div><div class="step-footer"><button data-go="content">← Metinler</button><button data-go="artwork">Görsellere geç →</button></div></section>
<section id="artwork" class="hidden"><div class="card"><h2>4. Görselleri ekle — gerekiyorsa</h2><p class="hint">Mağazadaki görsellerin zaten uygunsa bu adımı geçebilirsin. Yeni görseller yüklemek için yukarıdan dil, aşağıdan cihaz/görsel türü seç. PNG/JPEG dosyalarını ekle; boyutları otomatik kontrol edilir.</p><div class="row"><div><label for="group">Cihaz veya görsel türü</label><select id="group"></select></div><div><label for="images">Görsel dosyaları</label><input type="file" id="images" accept="image/png,image/jpeg" multiple></div></div><p class="hint">Görseldeki yazıları bu araç çevirmiyor. Her dil için hazır görsel ekle. Oklarla yükleme sırasını değiştirebilirsin.</p><div class="gallery" id="gallery"></div></div><div class="step-footer"><button data-go="translation">← Çeviri</button><button data-go="release">Göndermeye geç →</button></div></section>
<section id="release" class="hidden"><div class="card"><h2>5. Hazır içeriği mağazaya gönder</h2><p class="hint">Bu bölüm metin/görselleri gönderir; uygulama build'i oluşturmaz. Önce yükleme planını kontrol et, sonra gönder. Apple incelemesi veya Google production dağıtımı başlatılmaz.</p><p id="uploadReadiness" class="notice"></p><div class="row"><div><label for="uploadPlatform">Mağaza</label><select id="uploadPlatform"><option value="ios,android">İki mağaza</option><option value="ios">App Store</option><option value="android">Google Play</option></select></div><div><label for="scope">Ne göndereceksin?</label><select id="scope"><option value="metadata">Uygulama metinleri</option><option value="images">Görseller</option><option value="notes">Sürüm notları</option><option value="all">Metinler, görseller ve notlar</option></select></div></div><div id="googleReleaseFields" class="hidden"><p class="hint">Google sürüm notları için mağazada zaten bulunan build numarasını ve kanalını seç. Yeni build göndermek istiyorsan aşağıdaki uygulama build bölümünü kullan.</p><div class="row"><div><label for="versionCode">Google build numarası (version code)</label><input id="versionCode" type="number" min="1" placeholder="Örnek: 42"></div><div><label for="track">Google yayın kanalı</label><select id="track"><option value="internal">Dahili test (internal)</option><option value="alpha">Kapalı test (alpha)</option><option value="beta">Açık test (beta)</option><option value="production">Production</option></select></div></div></div><details><summary>İleri yükleme seçenekleri</summary><label for="appVersion">Apple düzenlenecek sürüm (isteğe bağlı)</label><input id="appVersion" placeholder="Örnek: 1.2.0"><label class="check"><input id="replaceImages" type="checkbox">Gönderilen Apple dillerinin mevcut ekran görüntülerini değiştir</label><p class="hint">Bu seçenek ilgili dillerdeki bütün Apple cihaz setlerini temizleyebilir. Google yalnızca gönderilen görsel gruplarını değiştirir.</p><div class="row buttons"><button id="export">Fastlane dosyalarını dışa aktar</button><button id="pull">Mağazadaki metinlerle karşılaştır</button><button id="pullApply">Mağaza metinlerini yedekleyerek içe al</button></div></details><div class="row buttons"><button id="dryRun">1. Yükleme planını kontrol et</button><button class="primary" id="push">2. İçeriği gönder</button></div></div><details class="card"><summary>Yeni uygulama build'i göndereceğim</summary><p class="hint">Yalnızca yeni AAB/IPA göndereceksen bu bölüm gerekir. Mağaza metinleri için imzalama kurulumu yapmana gerek yok.</p><p id="buildReadiness" class="notice"></p><div class="row"><div><label for="target">Build hedefi</label><select id="target"><option value="internal">TestFlight / Google dahili test taslağı</option><option value="production">App Store / Google production taslağı</option></select></div><label class="check"><input id="uploadOnly" type="checkbox">Zaten oluşturulmuş build'i gönder</label><label class="check"><input id="withStore" type="checkbox">Mağaza içeriklerini de gönder</label></div><div class="row buttons"><button id="deployPlan">Build planını gör</button><button class="primary" id="deploy">Build oluştur ve gönder</button></div><p class="hint">Google build'leri taslak kalır. Production dağıtımı için CLI release-status seçeneğini kullan. Apple inceleme gönderimi ayrıdır.</p></details><div class="step-footer"><button data-go="artwork">← Görseller</button><button data-go="home">Durum ekranına dön</button></div></section>
<section id="setup" class="hidden"><div class="card"><h2>1. Proje kurulumu</h2><p id="setupSummary" class="notice"></p><p class="hint">Mevcut değerler aşağıda görünür. Hazırsa yeniden kaydetmen gerekmez. İçerik hazırlamak için uygulama adı ve kaynak dil yeterlidir; hesap bilgilerini göndermeden önce tamamlayabilirsin.</p><form id="setupForm"><div class="grid" id="setupFields"></div><div class="row buttons"><button class="primary" type="submit">Ayarları kaydet</button><button type="button" id="syncScaffold">Eksik/güncel olmayan dosyaları tamamla</button></div></form></div><div class="card" id="appleCard" data-store="ios"><h3>App Store bağlantısı</h3><p id="appleStatus" class="notice"></p><details id="appleImport"><summary>Apple anahtarı ekle / değiştir</summary><ol class="steps"><li><a href="https://appstoreconnect.apple.com/access/integrations/api" target="_blank" rel="noreferrer">App Store Connect API anahtarları</a> sayfasını aç.</li><li>Team API key oluşturup .p8 dosyasını indir. Mevcut anahtarın varsa yenisini oluşturma.</li><li>Key ID / Issuer ID'yi proje ayarlarına yazıp kaydet; dosyayı aşağıdan seç.</li></ol><label for="appleKey">Apple .p8 dosyası</label><input id="appleKey" type="file" accept=".p8"><details><summary>Birden fazla projede kullanacağım</summary><label for="appleProfile">Profil adı (isteğe bağlı)</label><input id="appleProfile" placeholder="company-apple"></details><button id="importApple">Anahtarı bu projeye ekle</button></details><div class="row buttons"><button id="verifyApple">Mağaza erişimini kontrol et</button></div></div><div class="card" id="googleCard" data-store="android"><h3>Google Play bağlantısı</h3><p id="googleStatus" class="notice"></p><details id="googleImport"><summary>Google kimlik dosyası ekle / değiştir</summary><ol class="steps"><li><a href="https://console.cloud.google.com/iam-admin/serviceaccounts" target="_blank" rel="noreferrer">Google Cloud</a> üzerinden service account oluştur; Google Play Developer API'yi aç.</li><li><a href="https://play.google.com/console" target="_blank" rel="noreferrer">Play Console</a>'da service account e-postasına uygulama erişimi ver.</li><li>JSON dosyasını aşağıdan seç. Mevcut geçerli dosyan varsa bunları tekrar yapma.</li></ol><label for="googleKey">Google JSON dosyası</label><input id="googleKey" type="file" accept=".json"><details><summary>Birden fazla projede kullanacağım</summary><label for="googleProfile">Profil adı (isteğe bağlı)</label><input id="googleProfile" placeholder="company-google"></details><button id="importGoogle">Dosyayı bu projeye ekle</button><p class="hint">Yeni Google uygulamasının ilk build'i Play Console'dan yüklenmelidir. WIF/OAuth ve yardımcı CLI komutları doc/automation.md rehberinde açıklanır.</p></details><div class="row buttons"><button id="verifyGoogle">Mağaza erişimini kontrol et</button></div></div><div class="card"><h3>Build araçları — yalnızca build/yükleme için</h3><p id="toolSummary" class="notice">Henüz kontrol edilmedi. Metin ve çeviri hazırlamak için bu adımı geçebilirsin.</p><div class="row buttons"><button id="checkTools">Araçları kontrol et</button><button id="tools">Fastlane / CocoaPods eksiklerini düzelt</button></div><details><summary>Uygulama imzalama kontrolü</summary><p id="signingSummary" class="hint"></p><p class="hint">Dosyaların bulunması tek başına imzalamanın çalıştığını kanıtlamaz. Başarılı mevcut release build'in varsa yeni anahtar üretme. Android için mevcut upload keystore'unu kullan; iOS için mevcut Xcode ayarlarını koru veya Fastlane match ile eşitle.</p><pre>torchinlane signing android --help
torchinlane signing sync --help</pre></details></div><div class="step-footer"><button data-go="home">← Durum ekranı</button><button data-go="content">Metinlere geç →</button></div></section>
<details class="card" id="activity"><summary>İşlem ayrıntıları · <span id="jobStatus">Beklemede</span></summary><pre id="logs" aria-live="polite">Henüz işlem başlatılmadı.</pre></details><footer>Dosyalar bilgisayarında kalır. Çeviri görevini paylaştığın ajan metinleri görür. Mağazaya gönderme işlemi Apple/Google'a bağlanır.</footer></main>
<script>

'use strict';
let token=location.hash.slice(1);try{if(token)sessionStorage.setItem('torchinlane-session',token);else token=sessionStorage.getItem('torchinlane-session')||'';history.replaceState(null,'',location.pathname);}catch(e){}const $=id=>document.getElementById(id);
let activeTab='home',nextTab='setup',setupDirty=false;
let state={},current={fields:{},images:{}},dirty=false,polling=false,loadedPlatform='',loadedLocale='';
const labels={name:'Uygulama adı',subtitle:'Alt başlık',description:'Uzun açıklama',keywords:'Anahtar kelimeler',promotional_text:'Tanıtım metni',support_url:'Destek bağlantısı',marketing_url:'Tanıtım sitesi',privacy_url:'Gizlilik politikası bağlantısı',release_notes:'Bu sürümde neler değişti?',title:'Uygulama adı',short_description:'Kısa açıklama',full_description:'Uzun açıklama',video:'YouTube video bağlantısı'};
function status(s){$('status').textContent=s;}
async function api(path,data){const res=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'X-Torchinlane-Token':token,'Content-Type':'application/json'},...(data===undefined?{}:{body:JSON.stringify(data)})});const result=await res.json();if(!res.ok)throw Error(result.error||'Request failed');return result;}
function safely(fn){return async event=>{try{await fn(event);}catch(e){status(e.message);}};}
function options(select,values,selected){select.replaceChildren();for(const value of values){const option=document.createElement('option');option.value=value;option.textContent=select.id==='group'?(groupLabels[value]||value):localeLabel(value);select.append(option);}if(values.includes(selected))select.value=selected;}
async function refresh(){state=await api('/api/state');$('appName').textContent=state.appName;const selected=selectedPlatforms();if(!selected.includes($('platform').value))$('platform').value=selected[0];const platform=$('platform').value;options($('locale'),state.locales[platform],$('locale').value);const additions=state.available[platform].filter(l=>!state.locales[platform].includes(l)&&l!==state.readiness.platforms[platform].sourceLocale);const suggested=['en-US','tr-TR','tr','de-DE','de','fr-FR','fr'].find(l=>additions.includes(l));options($('addLocale'),additions,suggested);$('addLocaleButton').disabled=additions.length===0;for(const option of $('platform').options)option.disabled=!selected.includes(option.value);options($('from'),state.locales[platform],state.readiness.platforms[platform].sourceLocale);options($('group'),state.groups[platform],$('group').value);$('translate').disabled=!state.aiAvailable;renderSetup();renderReadiness();$('from').disabled=true;await loadContent();renderTranslation();renderRelease();}
function tab(name){activeTab=name;for(const section of ['home','content','translation','artwork','release','setup'])$(section).classList.toggle('hidden',section!==name);$('contentContext').classList.toggle('hidden',!['content','translation','artwork'].includes(name));$('locale').parentElement.classList.toggle('hidden',name==='translation');document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));if(name==='translation')renderTranslation();if(name==='release')renderRelease();}
for(const button of document.querySelectorAll('[data-tab]'))button.onclick=()=>tab(button.dataset.tab);
for(const button of document.querySelectorAll('[data-go]'))button.onclick=()=>tab(button.dataset.go);
async function loadContent(){const platform=$('platform').value,locale=$('locale').value;$('editor').replaceChildren();$('gallery').replaceChildren();dirty=false;if(!locale){$('editor').textContent='Bu mağaza için henüz dil dosyası yok. Kaynak dili aç düğmesiyle oluşturabilirsin.';return;}loadedPlatform=platform;loadedLocale=locale;current=await api('/api/content?'+new URLSearchParams({platform,locale}));for(const [key,limit]of Object.entries(state.fields[platform])){const label=document.createElement('label');label.htmlFor='field_'+key;label.textContent=labels[key]||key;const input=document.createElement(limit===0||['name','title','subtitle','keywords'].includes(key)?'input':'textarea');input.id='field_'+key;input.dataset.field=key;input.value=current.fields[key]||'';const counter=document.createElement('div');counter.className='counter';const update=()=>{const isBytes=platform==='ios'&&key==='keywords';const length=isBytes?new TextEncoder().encode(input.value).length:Array.from(input.value).length;counter.textContent=limit?length+' / '+limit+(isBytes?' UTF-8 bytes':' karakter'):'URL';counter.classList.toggle('invalid',limit>0&&length>limit);};input.oninput=()=>{dirty=true;update();};update();let container=$('editor');if(['keywords','promotional_text','support_url','marketing_url','privacy_url','video'].includes(key)){let advanced=$('advancedFields');if(!advanced){advanced=document.createElement('details');advanced.id='advancedFields';const summary=document.createElement('summary');summary.textContent='İleri metin alanları ve bağlantılar';advanced.append(summary);$('editor').append(advanced);}container=advanced;}container.append(label,input,counter);}dirty=false;gallery();}
function gallery(){const platform=$('platform').value,group=$('group').value,paths=current.images[group]||[];$('gallery').replaceChildren();paths.forEach((path,index)=>{const card=document.createElement('div');card.className='image';const image=document.createElement('img');image.alt=path.split('/').pop();image.src='/asset?'+new URLSearchParams({path,token});const name=document.createElement('small');name.textContent=image.alt;card.append(image,name);for(const[caption,delta]of [['←',-1],['→',1]]){const b=document.createElement('button');b.textContent=caption;b.disabled=index+delta<0||index+delta>=paths.length;b.onclick=safely(async()=>{const order=paths.slice();[order[index],order[index+delta]]=[order[index+delta],order[index]];await api('/api/reorder',{platform,locale:$('locale').value,group,paths:order});await reloadImages();});card.append(b);}const remove=document.createElement('button');remove.textContent='Dosyayı kaldır';remove.onclick=safely(async()=>{await api('/api/delete-image',{path});await reloadImages();});card.append(remove);$('gallery').append(card);});}
async function reloadImages(){const data=await api('/api/content?'+new URLSearchParams({platform:$('platform').value,locale:$('locale').value}));current.images=data.images;gallery();}
$('platform').onchange=safely(async()=>{if(dirty){$('platform').value=loadedPlatform;throw Error('Mağaza değiştirmeden önce metinleri kaydet.');}await refresh();$('taskPanel').classList.add('hidden');});
$('locale').onchange=safely(async()=>{if(dirty){$('locale').value=loadedLocale;throw Error('Dil değiştirmeden önce metinleri kaydet.');}await loadContent();});
$('group').onchange=gallery;
$('save').onclick=safely(async()=>{const fields={};document.querySelectorAll('[data-field]').forEach(input=>fields[input.dataset.field]=input.value);await api('/api/save',{platform:$('platform').value,locale:$('locale').value,fields});dirty=false;await refresh();status('Metinler kaydedildi. İstersen şimdi çeviri adımına geç.');});
$('addLocaleButton').onclick=safely(async()=>{if(dirty)throw Error('Önce metinleri kaydet.');await api('/api/init',{platform:$('platform').value,locales:[$('addLocale').value]});await refresh();});
