async function poll(){polling=true;try{const job=await api('/api/job');$('logs').textContent=job.logs.join('\n')||'Başlıyor…';if(job.running)$('jobStatus').textContent='Çalışıyor…';if(job.running)setTimeout(poll,1000);else{polling=false;setBusy(false);await refresh();$('jobStatus').textContent=job.exitCode===null?'Beklemede':job.exitCode===0?'Tamamlandı':'Hata oluştu';status(job.exitCode===0?'İşlem tamamlandı. Durum bilgileri yenilendi.':'İşlem tamamlanamadı. Ayrıntıları aşağıdan kontrol et.');}}catch(e){polling=false;setBusy(false);status(e.message);}}
