const keyOk=r.credential==='present'&&r.credentialIdsReady;addCheck(list,'Mağaza kimlik dosyası',keyOk,keyOk?'Geçerli dosya bulundu. Yeniden indirmen veya eklemen gerekmiyor.':r.credential==='invalid'?'Dosya okunuyor ama biçimi geçersiz. Doğru dosyayı seç.':r.credential==='present'?'Anahtar bulundu; Apple Key ID eksik. Ayarlardan tamamla.':'Henüz eklenmemiş. Metin/çeviri hazırlarken bu adımı geçebilirsin.',keyOk?'Bağlantıyı gör':'Bağlantıyı kur','setup',!keyOk);
