const neededTools=['ruby','fastlane',...(platform==='ios'?['pod','xcodebuild']:[])],toolStates=state.readiness.tools,toolsOk=neededTools.every(t=>toolStates[t]?.ok);addCheck(list,'Yükleme araçları',toolsOk,toolsOk?'Ruby/Fastlane'+(platform==='ios'?' ve iOS araçları':'')+' çalışıyor. Tekrar kurulum gerekmez.':'Henüz tam kontrol edilmedi veya eksik araç var. Metin hazırlamak için gerekmez.','Araçları kontrol et','setup','Kontrol edilmedi');
