for(const [platform,prefix] of [['ios','apple'],['android','google']]){const r=state.readiness.platforms[platform];$(prefix==='apple'?'appleCard':'googleCard').classList.toggle('hidden',!selected.includes(platform));$(prefix+'Status').textContent=r.verified?'✓ Mağaza erişimi bu oturumda doğrulandı. Başka işlem gerekmiyor.':r.credential==='present'?(r.credentialIdsReady?'✓ Kimlik dosyası bulundu; yeniden ekleme gerekmez. Erişim henüz kontrol edilmedi.':'Kimlik dosyası bulundu. Apple Key ID ayarını tamamla.'):(r.credential==='invalid'?'Kimlik dosyası geçersiz. Aşağıdan doğru dosyayı seç.':'Kimlik dosyası bulunamadı. İçerik hazırlamak için bu adımı geçebilirsin.');$(prefix+'Import').open=r.credential!=='present';const verify=$(prefix==='apple'?'verifyApple':'verifyGoogle');verify.disabled=!localUploadReady(platform)||r.verified;verify.textContent=r.verified?'✓ Erişim doğrulandı':'Mağaza erişimini kontrol et';}
const required=['ruby','fastlane',...(selected.includes('ios')?['pod','xcodebuild']:[])],tools=state.readiness.tools;const checked=required.filter(t=>tools[t]);$('toolSummary').textContent=checked.length?required.map(t=>t+': '+(!tools[t]?'henüz kontrol edilmedi':tools[t].ok?'hazır':'eksik / çalışmıyor')).join(' · '):'Henüz kontrol edilmedi. Metin ve çeviri için gerekmez; göndermeden önce kontrol edebilirsin.';const allOk=required.every(t=>tools[t]?.ok);$('tools').disabled=allOk;$('tools').textContent=allOk?'✓ Mağaza araçları hazır':'Fastlane / CocoaPods eksiklerini düzelt';$('signingSummary').textContent=selected.map(p=>storeName(p)+': '+(state.readiness.platforms[p].signing==='configured'?'Android imzalama ayar dosyası bulundu; Gradle ve keystore ile build doğrulaması gerekir.':state.readiness.platforms[p].signing==='export-options'?'iOS export ayarları bulundu; sertifika/provisioning bu kontrolde doğrulanmadı.':'Yerel imzalama kanıtı yok; yalnızca yeni build oluşturacaksan kontrol et.')).join('\n');}
function renderTranslation(){const p=$('platform').value,r=state.readiness.platforms[p],source=r.sourceLocale;$('contextHint').textContent=storeName(p)+' · Kaynak dil: '+(source?localeLabel(source):'Bu mağazada desteklenmiyor');$('sourceHint').textContent=source?'Kaynak dilin '+localeLabel(source)+'. Çeviri diğer dillere bu metinlerden yapılır.':'Kaynak dil bu mağazada desteklenmiyor. Kurulumda değiştir.';$('translationProgress').textContent=r.textIssues.length?'Önce Metinler adımındaki biçim/uzunluk hatalarını düzelt.':!r.sourceReady?'Önce Metinler adımında kaynak dili doldur.':!r.targets.length?'Kaynak metin hazır. Çevirmek istediğin ilk dili aşağıdan ekle.':r.pendingFields?r.targets.length+' hedef dil · '+r.pendingFields+' alan eksik. Görev bunları dolduracak.':'✓ Eklenen dillerde boş çeviri alanı yok. Bu adımı geçebilirsin.';$('prepareTask').disabled=!r.sourceReady||r.textIssues.length>0||!r.targets.length||(r.pendingFields===0&&!$('overwrite').checked);$('copySource').disabled=!state.readiness.platforms[p==='ios'?'android':'ios'].sourceReady;}
